#!/usr/bin/env python3
"""Illustrated original-course covers and complete no-JS reading routes."""
from pathlib import Path
import json,html,re,base64,textwrap
R=Path(__file__).resolve().parent.parent;P=R/'apps/web/public';e=lambda x:html.escape(str(x),quote=True)
courses=json.loads((P/'courses.json').read_text());scope=json.loads((R/'curriculum/expansion/scope.json').read_text());new=[c for c in courses if c.get('sourceListingNumber')]
art=['paper-decoder','negative-space','fruit-classifier','style-comparison','document-extraction','json-data','reasoning-check','faq-from-friction','sql-reference','connection-graph','concept-map','infinite-explainer','api-explainer','synthetic-focus-group','feedback-classifier','source-verifier','spreadsheet-lookup','thread-actions','moderation-review','debate-opponent','automation-blueprint','framing-audit','audio-to-actions','markdown-structure','few-shot-summary','audience-rewrite','contrast-check','visual-priority','own-style-profile','ui-wireframe']
assert len(art)==len(set(art))==30 and all(0<=c['expansionIndex']<30 for c in new)
for c,a in ((c,art[c['expansionIndex']]) for c in new):
 data=base64.b64encode((R/'branding/activity-art'/f'{a}.webp').read_bytes()).decode();lines=textwrap.wrap(c['title'],23)[:3]
 title=''.join(f'<text x="28" y="{354+34*i}" fill="#fff5e5" font-family="Georgia,serif" font-size="28" font-weight="bold">{e(t)}</text>' for i,t in enumerate(lines))
 svg=f'''<svg xmlns="http://www.w3.org/2000/svg" width="410" height="520" viewBox="0 0 410 520" role="img" aria-labelledby="title desc"><title id="title">{e(c['title'])}</title><desc id="desc">Original project course with {len(c['lessons'])} guided activities. Colour illustration reused from Open Practice's own {e(a)} collection artwork; new authored cover typography.</desc><defs><linearGradient id="shade" x2="0" y2="1"><stop stop-color="#33241a" stop-opacity="0"/><stop offset=".38" stop-color="#33241a" stop-opacity=".92"/><stop offset="1" stop-color="#43180f"/></linearGradient></defs><rect width="410" height="520" fill="#7c1f16"/><image width="410" height="520" href="data:image/webp;base64,{data}" preserveAspectRatio="xMidYMid slice"/><rect x="18" y="18" width="374" height="48" rx="6" fill="#43180f" fill-opacity=".94"/><text x="30" y="38" font-family="Arial,sans-serif" font-size="10" fill="#f5d6a8" letter-spacing="1">THE OPEN PRACTICE COLLECTION</text><text x="30" y="55" font-family="Arial,sans-serif" font-size="9" fill="#fff5e5">PROJECT {c['num']} / {e(c['track'].upper())}</text><rect y="259" width="410" height="261" fill="url(#shade)"/>{title}<path d="M28 445h354" stroke="#d4971b"/><text x="28" y="468" font-family="Arial,sans-serif" font-size="10" fill="#f5d6a8">PRACTICAL AI ENGINEERING</text><text x="28" y="491" font-family="Georgia,serif" font-size="15" fill="#fff5e5">Six guided activities / {e(c['level'])}</text><text x="28" y="510" font-family="Arial,sans-serif" font-size="8" fill="#d9b78f">BUILD / BREAK / CHECK / KEEP THE EVIDENCE</text></svg>'''
 (P/'brand/covers'/f'{c["id"]}.svg').write_text(svg)
base=(P/'library.html').read_text();head=base.split('<main>')[0];footer='<footer>'+base.split('<footer>',1)[1].split('</footer>',1)[0]+'</footer>';folder=P/'builds';folder.mkdir(exist_ok=True)
def page(id,title,body):
 h=re.sub(r'<title>.*?</title>','<title>'+e(title)+' · Open Practice</title>',head).replace(' aria-current="page"','')
 h=h.replace('</head>',f'<link rel="canonical" href="https://open-practice.zlnew.workers.dev/builds/{id}.html"></head>')
 (folder/f'{id}.html').write_text(h+'<main><article class="reading-page">'+body+'</article></main>'+footer+'<script type="module" src="/learner.js"></script><script type="module" src="/growth.js"></script></body></html>')
for c in courses:
 body=f'<section class="info-hero"><div><div class="eyebrow">PROJECT {c["num"]} / {e(c["track"])}</div><h1>{e(c["title"])}</h1><p>{e(c["description"])}</p><p>{e(c.get("level","Foundation"))} · {e(c["time"])} · {len(c["lessons"])} activities</p><div class="actions"><a class="primary" href="/?course={c["id"]}">Open editable workspace →</a><a href="{c["downloads"]["pack"]}" download>Complete practice pack ↓</a><a href="{c["downloads"]["handbook"]}" download>Handbook ↓</a></div></div><img src="/brand/covers/{c["id"]}.svg?v=illustrated-20261021" width="410" height="520" alt="{e(c["title"])} — illustrated handbook"></section><section><h2>Before you begin</h2><ul>'+''.join('<li>'+e(x)+'</li>' for x in c['prerequisites'])+'</ul><p>Free original, non-accredited practice. Self-review is not independent assessment. No particular provider, payment platform or country is mandatory; use a legitimate available route or explicitly labelled manual practice.</p></section>'
 for i,l in enumerate(c['lessons'],1):
  if l.get('moduleId') and (i==1 or c['lessons'][i-2].get('moduleId')!=l['moduleId']):body+=f'<h2 class="module-heading" id="{e(l["moduleId"])}">Module: {e(l["module"])}</h2>'
  body+=f'<section id="activity-{i}"><div class="eyebrow">ACTIVITY {i} / {l["estimatedMinutes"]} MIN ESTIMATED</div><h2>{e(l["title"])}</h2><p class="lesson-explanation">{e(l["text"])}</p><h3>Worked example</h3><pre>{e(l["example"])}</pre><h3>Your practical task</h3><ol>'+''.join('<li>'+e(x)+'</li>' for x in l['steps'])+'</ol><h3>Evidence to keep</h3><ul>'+''.join('<li>'+e(x)+'</li>' for x in l['expected'])+'</ul><h3>Mistakes to watch for</h3><ul>'+''.join('<li>'+e(x)+'</li>' for x in l['commonMistakes'])+'</ul><h3>Check your understanding</h3><p>'+e(l['selfCheck'])+'</p><h3>No-service / offline route</h3><p>'+e(l['offline'])+'</p></section>'
 body+='<section><h2>Capstone self-review</h2><p>'+e(c['capstone']['scoring'])+'</p><ul>'+''.join('<li><strong>'+e(r['title'])+(' — critical' if r['critical'] else '')+'</strong>: '+e(r['evidence'])+'</li>' for r in c['capstone']['rubric'])+'</ul><h2>Review questions</h2>'
 for q in c['assessment']:body+='<details><summary>'+e(q['question'])+'</summary><p>'+e(q['options'][q['answer']])+'</p><p>'+e(q['explanation'])+'</p></details>'
 body+='<h2>Practice files</h2><ul>'+''.join('<li><a href="'+e(x['url'])+'" download>'+e(x['title'])+'</a></li>' for x in c['fixtureFiles'])+'</ul><h2>References and editorial limits</h2><p>'+e(c['editorialStatus'])+'</p><ul>'+''.join('<li><a href="'+e(x['url'])+'" rel="noopener noreferrer">'+e(x['title'])+'</a></li>' for x in c['references'])+'</ul><p><a href="/builds/index.html">Browse all build paths →</a> · <a href="/curriculum.html">Curriculum overview</a></p></section>'
 page(c['id'],c['title'],body)
intro='<section><div class="eyebrow">'+str(len(courses))+' ORIGINAL BUILD PATHS / READ WITHOUT JAVASCRIPT</div><h1>Choose a useful project.</h1><p>'+str(len(courses))+' project paths, each ending in a real deliverable. Overlapping paths are merged into modules, so nothing is repeated. For people across regions underserved or excluded by mainstream providers—not one country. All original lessons, fixtures and handbooks are free to download. Hosted services have their own eligibility, privacy and quota conditions.</p><p>Advanced prerequisites are labelled. No local AI model download, payment platform or account signup is required to read. A manual reference exercise is not a live model run.</p></section>'
for label in dict.fromkeys(c['track'] for c in courses):
 intro+='<section><h2>'+e(label)+'</h2><ul>'+''.join('<li><a href="/builds/'+c['id']+'.html">'+e(c['title'])+'</a> — '+e(c.get('level','Foundation'))+'</li>' for c in courses if c['track']==label)+'</ul></section>'
intro+='<section><h2>Published scope</h2><p>Thirty strong-fit topics were built as original courses. Eleven supporting inputs are embedded inside related lessons. The twenty-seven conditional and six held topics were not published. No affiliation, accreditation or copied course material is implied.</p><a href="/resources/expansion-scope.json" download>Download the exact topic-to-course and supporting-lesson map ↓</a></section>'
page('index','Choose a practical project',intro)
(P/'resources/expansion-scope.json').write_text(json.dumps(scope,indent=2)+'\n')
# Accurate public counts, including the unchanged standalone activity library.
m=json.loads((P/'curriculum.json').read_text());activities=json.loads((P/'activities.json').read_text());total_lessons=m['lessons']+activities['total'];hours=round((m['estimatedMinutes']+activities['guidedMinutes'])/60)
p=P/'index.html';s=p.read_text();s=s.replace('Explore six practical AI build paths.','Explore 36 practical AI build paths.');s=s.replace('<strong>6</strong><span>Build paths</span>',f'<strong>{len(courses)}</strong><span>Build paths</span>');s=re.sub(r'<strong>\d+</strong><span>Activities</span>',f'<strong>{total_lessons}</strong><span>Activities</span>',s);s=re.sub(r'<strong>\d+</strong><span>Free resources</span>',f'<strong>{m["resources"]}</strong><span>Free resources</span>',s);s=re.sub(r'<strong>~\d+h</strong>',f'<strong>~{hours}h</strong>',s);s=s.replace('BUILD PATH 1 OF 6','BUILD PATH 1 OF 36')
notice='<section class="hub-note region-access"><div class="eyebrow">ACCESS SHOULD NOT DEFINE YOUR POTENTIAL</div><h2>Useful practice, wherever providers leave gaps.</h2><p>For people across underserved and excluded regions. Check country eligibility, language, identity requirements, cost, quotas and data terms before choosing a service. Use legitimate available alternatives; never false residency or restriction bypasses. Downloaded lessons and fictional fixtures remain useful without a live provider.</p><a class="primary" href="/builds/index.html">Browse all '+str(len(courses))+' paths and prerequisites →</a> <a href="/?course=make-mula">Make Mula: useful work, honest offers →</a></section>'
if 'class="hub-note region-access"' not in s:s=s.replace('<section class="features"',notice+'<section class="features"',1)
p.write_text(s)
p=P/'dashboard.html';s=p.read_text();s=re.sub(r'(<a href="/library.html"><strong>)\d+( ↗</strong><span>FREE LIBRARY RESOURCES)',lambda x:x[1]+str(m['resources'])+x[2],s);p.write_text(s)
p=P/'curriculum.html';s=p.read_text().replace('CURRICULUM 2.0','CURRICULUM 3.0').replace('Six practical foundations.','Six foundations plus thirty original project paths.').replace('Cloud-AI activities use your own authorised account; no-key alternatives are described, but simulation is not a live integration.','Cloud-AI activities use a legitimate service available to you; eligibility varies across regions. Manual alternatives are described, but simulation is not a live integration.');s=re.sub(r'(<strong id="stat-paths">).*?(</strong>)',lambda x:x[1]+str(m['paths'])+x[2],s);s=re.sub(r'(<strong id="stat-activities">).*?(</strong>)',lambda x:x[1]+str(m['lessons'])+x[2],s);s=re.sub(r'(<strong id="stat-hours">).*?(</strong>)',lambda x:x[1]+str(round(m['estimatedMinutes']/60))+x[2],s);s=re.sub(r'(<strong id="stat-resources">).*?(</strong>)',lambda x:x[1]+str(m['resources'])+x[2],s);s=s.replace('This release develops foundational workflows and small builds.','This release adds original project courses to the foundations.');p.write_text(s)
p=P/'library.html';s=p.read_text();s=re.sub(r'(<p id="hub-results"[^>]*>)\d+ illustrated resources',lambda x:x[1]+str(m['resources'])+' illustrated resources',s);p.write_text(s)
p=P/'sitemap.xml';s=p.read_text();urls=['/builds/index.html']+['/builds/'+c['id']+'.html' for c in courses]
for url in urls:
 if 'https://open-practice.zlnew.workers.dev'+url not in s:s=s.replace('</urlset>','<url><loc>https://open-practice.zlnew.workers.dev'+url+'</loc></url></urlset>')
p.write_text(s)
print(f'Built {len(courses)} readable build paths, directory, regional access guidance and accurate public counts.')
